-- =============================================================================
-- requirement_conflicts_seed_group_c.sql -- what the rules asset does NOT know
-- about IL, OH, IN, WI, MN, IA, MO, KS, NE, ND, SD, MT.
--
-- Three kinds of row live here, and all are deliberately left OPEN
-- (resolution = 'unresolved'), which blocks auto-clear (PRD 8.1 condition 6)
-- and raises RULE_UNCERTAIN (PRD 8.3):
--
--   A. GAPS -- a field_key in scope for a state/license_type for which no
--      primary source could be found and read on 2026-09-18. requirement_id is
--      NULL because no requirements row was written. published_value is NULL;
--      notes say what was searched and what remains open.
--
--   B. QUALIFIERS -- a requirements row EXISTS but a second official source, or
--      a statutory exception, narrows or contradicts it. requirement_id points
--      at the row. These are the rows that stop a confidently-wrong obligation.
--
--   C. DISAGREEMENTS -- two official sources publish different figures for the
--      same thing. The seeded value is what the licensee actually pays or does;
--      the other figure is recorded here.
--
-- observed_by is 'research-agent-group-c' throughout: these are desk-research
-- findings, not observed board behaviour.
--
-- Run AFTER requirements_seed_group_c.sql. Idempotent. Touches only rows this
-- agent owns, so it coexists with requirement_conflicts_seed.sql and with other
-- agents' state groups.
-- =============================================================================

begin;

delete from requirement_conflicts where observed_by = 'research-agent-group-c';

-- ---------------------------------------------------------------------------
-- B/C. QUALIFIERS AND DISAGREEMENTS on rows that exist.
-- ---------------------------------------------------------------------------
insert into requirement_conflicts
  (requirement_id, published_value, observed_value, observed_at, observed_by,
   occurrences, resolution, notes)
select r.id, c.published_value, c.observed_value,
       timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved', c.notes
from (values

 ('IL','MD','ce_hours_total',
  '150 hours of CME per 3-year cycle',
  'figure published in a reinstatement instruction sheet, not a renewal CE page',
  'The 150-hour figure, the 60-hour formal minimum and the 90-hour informal maximum were read from IDFPR''s Physician and Surgeon REINSTATEMENT instruction packet (https://idfpr.illinois.gov/content/dam/soi/en/web/idfpr/renewals/apply/forms/f2409.pdf and .../physician-less3-reinstatement.pdf). IDFPR''s own Continuing Education landing page publishes only the legislative topic mandates and says "Review your profession''s Act and Rules to determine any continuing education (CE) requirements that may apply". The authoritative text is 68 Ill. Adm. Code 1285.110, which could NOT be fetched: every ilga.gov URL form tried (ftp/JCAR/AdminCode, /agencies/JCAR/EntirePart, /documents/legislation/ilcs, /Legislation/ILCS/Articles) returned ROBOTS_DISALLOWED or a robots.txt TLS failure on 2026-09-18. OPEN: read 68 Ill. Adm. Code 1285.110 by hand and confirm the renewal figure equals the reinstatement figure. A reinstatement requirement is USUALLY the renewal requirement, but "usually" is not verified.'),

 ('IL','MD','renewal_cycle_months',
  '36 months (Section 1285.120, per IDFPR physician FAQ)',
  'the Department has repeatedly extended the deadline by variance',
  'IDFPR''s physician page on 2026-09-18 stated "The renewal deadline for the following licenses has been extended to August 31, 2026" for Physician and Surgeon and Licensed Physician Controlled Substance licences, and the Department publishes a dated variance document for the 2026 renewal. The underlying cycle is triennial, but the EFFECTIVE expiry date in a given cycle has been moved administratively at least once. An obligation calendar built on a fixed 36-month step from last renewal may be wrong by weeks. OPEN: decide whether the platform models board-issued deadline variances at all. Source: https://idfpr.illinois.gov/profs/physicians.html'),

 ('OH','MD','ce_topic_ethics_hours',
  '1 hour, "duty to report misconduct under section 4731.224 of the Revised Code"',
  'the field_key vocabulary has no duty-to-report slot; mapped onto ethics',
  'VOCABULARY MAPPING, NOT A VALUE DISPUTE. OAC 4731-10-02 requires one hour on a licensee''s statutory duty to report misconduct. The available topic names are opioid, ethics, implicit_bias, human_trafficking, medical_errors, domestic_violence, hiv_aids, pain_management, controlled_substance, laws_and_rules, jurisprudence_ethics, impairment and pharmacotherapeutics. Duty-to-report is arguably ethics (professional responsibility) and arguably laws_and_rules (an Ohio statutory duty). It was mapped to ce_topic_ethics_hours to match the Texas precedent, where ce_topic_ethics_hours carries "medical ethics and/or professional responsibility". OPEN: a consumer searching for an Ohio laws-and-rules obligation will not find this row. Consider a ce_topic_duty_to_report_hours key.'),

 ('OH','APRN','collaborative_agreement_required',
  'true (standard care arrangement, ORC 4723.431)',
  'ORC 4723.431 names only CNS, CNM and CNP -- not CRNAs',
  'ORC 4723.431 requires a standard care arrangement of "an advanced practice registered nurse who is designated as a clinical nurse specialist, certified nurse-midwife, or certified nurse practitioner". Certified registered nurse anesthetists are APRNs in Ohio and are NOT named in that sentence. The seeded boolean true is the conservative default and is correct for the CNP population this asset mainly serves, but it over-states the duty for a CRNA. The same subset problem is handled with value_json on the Ohio pharmacology row; it is NOT handled here because a partly-true boolean at least fails safe. OPEN: the platform needs a per-clinician APRN role attribute before this boolean can be trusted for a CRNA. Source: https://codes.ohio.gov/ohio-revised-code/section-4723.431'),

 ('IN','APRN','ce_hours_total',
  '30 contact hours, at least 8 in pharmacology',
  'applicability (all advanced practice nurses vs prescribers only) not settled',
  'Indiana PLA''s Nursing Licensing Information page states the 30/8 requirement immediately alongside the prescriptive-authority discussion, so it is not clear on the face of the page whether it binds every Indiana advanced practice nurse or only those renewing prescriptive authority. The authoritative rule is 848 IAC 5 (Prescriptive Authority for Advanced Practice Nursing). The Indiana Administrative Rules portal at https://iar.iga.in.gov/latestArticle/848/5 is a JavaScript application that serves no static rule text to an automated fetch, and https://www.in.gov/pla/professions/indiana-state-board-of-nursing/continuing-education-requirements/ and .../advanced-practice-nurse/ both returned 404 on 2026-09-18. The row is seeded as an unconditional per-cycle 30 because that is the conservative reading; if it is in fact prescriber-only it should become value_json. OPEN: read 848 IAC 5 by hand. Source: https://www.in.gov/pla/professions/nursing-home/nursing-licensing-information'),

 ('WI','MD','ce_topic_opioid_hours',
  '2 of the 30 hours on prescribing opioids and other controlled substances',
  'DSPS states the duty for "the 2025 renewal", not as a standing requirement',
  'Wisconsin DSPS''s Physician Continuing Education page says "For the 2025 renewal, each license holder will be required to take two of the required 30 hours related to prescribing opioids and other controlled substances." A statement scoped to one named renewal cannot be assumed to recur, and the 2027 and 2029 renewals are not addressed. The value is therefore carried as value_json with the board''s scope recorded rather than as a recurring per-cycle 2. The authoritative rule is Wis. Admin. Code ch. Med 13, which could NOT be fetched: docs.legis.wisconsin.gov/code/admin_code/med/13 returned ROBOTS_DISALLOWED (robots.txt ConnectTimeout, then parse failure) on repeated attempts on 2026-09-18. OPEN: read Med 13.03 by hand and establish whether the two hours recur. Source: https://dsps.wi.gov/Pages/Professions/Physician/CE.aspx'),

 ('WI','APRN','collaborative_agreement_required',
  'true (collaborative relationship with a physician or dentist, Wis. Admin. Code N 8.10(7))',
  'DSPS describes a newer APRN credential with an independent-practice pathway that ch. N 8 does not reflect',
  'TWO OFFICIAL SOURCES DESCRIBE DIFFERENT REGIMES. Wis. Admin. Code sec. N 8.10(7) -- the advanced practice nurse PRESCRIBER rule -- says "Advanced practice nurse prescribers shall work in a collaborative relationship with a physician or dentist." But DSPS''s current Advanced Practice Registered Nurse page (https://dsps.wi.gov/Pages/Professions/APNP/Default.aspx) describes an APRN credential whose applicants must "demonstrate independent practice eligibility through supervised hours", and gives a renewal window opening in 2028 -- i.e. Wisconsin has moved from APNP certification to APRN licensure with a transition-to-practice tier, and ch. N 8 has not caught up. If that tier exists, this row is a value_json case with an hours threshold, exactly like MN, NE and SD, not a bare boolean. The bill text (2023 AB 154 / SB 145) at docs.legis.wisconsin.gov was ROBOTS_DISALLOWED on 2026-09-18 and the hour threshold was NOT read, so NO number was written -- inventing one would be the precise failure this table exists to avoid. OPEN: obtain the statutory transition-to-practice hour count and the effective date, then supersede this row with version 2 carrying value_json. THIS IS THE HIGHEST-VALUE OPEN ITEM IN GROUP C.'),

 ('NE','MD','ce_cycle_months',
  '24 months',
  'the Department states the expiry and the CE total on one page but never calls the CE period a biennium',
  'Nebraska DHHS''s Medicine and Surgery page states both "Licenses expire October 1 of every even year" and that "50 hours of Category 1 AMA approved continuing education" is required for renewal, but does not say in terms that the 50 hours are measured over the two years between renewals rather than, say, annually. The 24-month CE cycle is the only reading consistent with both sentences and is seeded on that basis, but it is one inferential step and is flagged rather than hidden. OPEN: confirm against 172 NAC or obtain a written statement. Source: https://dhhs.ne.gov/licensure/pages/medicine-and-surgery.aspx'),

 ('NE','MD','ce_topic_opioid_hours',
  '3 hours on opioids, of which 0.5 on the PDMP',
  'recurrence interval not stated by the Department',
  'The Department''s Controlled Substances Continuing Competency Requirement document states the hour counts and the population ("All Professionals Who Prescribe Controlled Substances", LB 731 / Neb. Rev. Stat. sec. 38-145(6)) but does not state how often the training must be repeated. The value_json carries periodicity "per_renewal_cycle" with an explicit "periodicity_confirmed": false so a consumer cannot mistake the assumption for a finding. An obligation generator MUST NOT emit a dated duty from this row until the interval is confirmed. OPEN: obtain the interval from the Licensure Unit or from Neb. Rev. Stat. sec. 38-145. Source: https://dhhs.ne.gov/licensure/Documents/ControlledSubstancesContCompReq.pdf'),

 ('ND','MD','renewal_cycle_months',
  '24 months (Board FAQ: licences expire "on your birthday every other year")',
  'NDAC 50-02-07.1-01 prices the licence "per year"',
  'TWO OFFICIAL SOURCES USE DIFFERENT UNITS. The Board of Medicine''s Physician FAQ says licences expire "on your birthday every other year" -- biennial. NDAC ch. 50-02-07.1 says "The fee for licensure in North Dakota, whether it be by qualification, compact, locum tenens, or special license, is two hundred dollars per year" and prices late renewal at "two hundred dollars per year, up to three years, for each year past the renewal deadline". The CYCLE is not in dispute (biennial is seeded); what is unresolved is the AMOUNT a biennial renewal costs, which is why no ND fee row was written at all -- see the ND fee gap below. OPEN: obtain the biennial renewal total from the Board. Sources: https://www.ndbom.org/practitioners/physicians/faqs.asp and https://ndlegis.gov/api/acdata/pdf/50-02-07.1.pdf'),

 ('MO','APRN','collaborative_agreement_required',
  'true (written collaborative practice arrangement, sec. 334.104.2 RSMo)',
  'no hours threshold retires it -- Missouri differs structurally from MN, NE and SD',
  'RECORDED SO THE BOOLEAN IS NOT READ AS THE SAME THING AS ITS NEIGHBOURS''. Minnesota (2,080 h), Nebraska (2,000 h) and South Dakota (1,040 h) all end the APRN''s dependent-practice duty at an hours threshold, and their rows are value_json for that reason. Missouri''s is a bare true because no Missouri source publishes any threshold, and the arrangement carries live operational constraints -- a 30-mile (non-HPSA) or 50-mile (HPSA) road distance limit, two-week physician review, annual review of the agreement, and physician review of at least 20% of controlled-substance cases -- that persist for the whole of the APRN''s career. A consumer must not normalise this to the tiered states'' shape. OPEN: confirm there is genuinely no threshold in RSMo ch. 334 or ch. 335; revisor.mo.gov refused automated access on 2026-09-18 ("appears a bot-like access pattern was detected"). Sources: https://pr.mo.gov/nursing-advanced-practice-nursing-collaborative.asp and https://www.sos.mo.gov/cmsimages/adrules/csr/current/20csr/20c2200-4.pdf'),

 ('MT','MD','ce_hours_total',
  '0 (Board: "Montana does not require Physicians to acquire CME")',
  'a zero is a real assertion and must not be silently treated as "unknown"',
  'NOT A DISPUTE -- A CONSUMER WARNING. Montana is the only state in Group C where a zero CE requirement is affirmatively published rather than merely absent, for both MD and APRN. A consumer that treats value_num = 0 as falsy and falls back to a default, or that treats the absence of a ce_cycle_months row as "unknown cycle" and suppresses the zero, will show a Montana physician an unknown CME status instead of the correct answer, which is none. No ce_cycle_months row is written for MT/MD or MT/APRN because a period for a zero requirement is meaningless. Source: https://boards.bsd.dli.mt.gov/medical-examiners/faq and https://boards.bsd.dli.mt.gov/nursing/continuing-education')

) as c(state, license_type, field_key, published_value, observed_value, notes)
join requirements r
  on r.state = c.state
 and r.license_type = c.license_type
 and r.field_key = c.field_key
 and r.is_current
 and r.deleted_at is null
 and r.verified_by = 'research-agent-group-c';

-- ---------------------------------------------------------------------------
-- A. GAPS -- in-scope field_keys with no verified value. requirement_id NULL.
-- ---------------------------------------------------------------------------
insert into requirement_conflicts
  (requirement_id, published_value, observed_value, observed_at, observed_by,
   occurrences, resolution, notes)
values

-- ---- ILLINOIS -------------------------------------------------------------
(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IL/MD/csr_required, IL/MD/csr_fee_cents, IL/MD/csr_renewal_cycle_months and the same three for IL/APRN. Illinois DOES issue a state controlled substances registration -- IDFPR''s physician page names "Licensed Physician Controlled Substance licenses" as a distinct credential it renews (https://idfpr.illinois.gov/profs/physicians.html), the physician reinstatement packet quotes controlled substances registration fees of "$5" for a new registration and "$15" for reinstatement, and the APRN CE FAQ speaks of "prescribers with Controlled Substances Registrations". But NO source read on 2026-09-18 states in terms that a prescriber MUST hold it, and the $5/$15 figures appear only in a reinstatement instruction sheet, not a fee schedule. A required-ness cannot be asserted from the existence of a credential, and a fee cannot be asserted from a reinstatement packet. NOT SEEDED -- neither the boolean nor the fee. OPEN: read the Illinois Controlled Substances Act (720 ILCS 570) sec. 302 and the IDFPR fee rule. This is a real recurring obligation the table currently does not carry for Illinois.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IL/APRN/collaborative_agreement_required and IL/APRN/supervision_required. Illinois runs a TWO-TIER APRN regime -- an ordinary APRN and a Full Practice Authority APRN (FPA-APRN), the two appearing side by side throughout IDFPR''s own CE FAQ. The instrument for the ordinary tier is a written collaborative agreement under the Nurse Practice Act (225 ILCS 65) and the FPA tier retires it after a practice-hour threshold. NEITHER THE INSTRUMENT NOR THE THRESHOLD WAS VERIFIED: IDFPR''s APRN/FPA instruction sheet at .../renewals/apply/forms/aprn-fpa.pdf returned 404 on 2026-08-18, and 68 Ill. Adm. Code 1300.465 (Full Practice Authority) and 225 ILCS 65/65-43 are on ilga.gov, which returned ROBOTS_DISALLOWED for every URL form tried. NOT SEEDED. Writing a bare true here would misstate the duty for every Illinois FPA-APRN, and writing false would misstate it for everyone else. OPEN: read 68 Ill. Adm. Code 1300.465 and 225 ILCS 65/65-43 by hand; the result is a value_json row carrying the hours threshold, not a boolean.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IL/MD/renewal_fee_cents, IL/APRN/renewal_fee_cents and IL/APRN/initial_license_fee_cents. IDFPR publishes physician and APRN fees in 68 Ill. Adm. Code 1285 and 1300 rather than on a web fee schedule, and both are on ilga.gov (ROBOTS_DISALLOWED throughout 2026-09-18). The physician reinstatement packet directs applicants to an interactive "Restoration/Reinstatement Fee Calculator" rather than printing amounts. Only IL/MD/initial_license_fee_cents ($500, from the physician licensing FAQ) could be verified. NOT SEEDED.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IL/MD and IL/APRN renewal_window_days, fingerprint_required. IDFPR''s License Renewal Information page (https://idfpr.illinois.gov/dpr/license-renewal-info.html) serves its expiry-date table from JavaScript ("Large data table content is loading...") and returns no static rows to an automated fetch. No IDFPR page read states either that fingerprints are required or that they are not, for medicine or for nursing. A negative cannot be asserted from silence. NOT SEEDED.'),

-- ---- OHIO -----------------------------------------------------------------
(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP OH/APRN/initial_license_fee_cents and OH/APRN/renewal_fee_cents. ORC sec. 4723.08 was read in full and gives $150 for an APRN licensure application and $135 for an APRN renewal -- but its own operative words are "The board of nursing MAY IMPOSE FEES NOT TO EXCEED the following limits". A statutory CAP is not the amount the licensee pays, and this seed''s fee convention is the amount actually paid. The Ohio Board of Nursing''s fee page (https://nursing.ohio.gov/page/rQSHYkYXmAGGAYIgT4jPz) and its APRN practice page are JavaScript applications that returned navigation chrome and no fee content on 2026-09-18. NOT SEEDED. Note the contrast: the Ohio MD fees ARE seeded because the State Medical Board publishes "$305.00" as the charged amount on its own physician page. OPEN: obtain the Board of Nursing''s charged fee schedule.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP OH/MD/csr_required and OH/APRN/csr_required. No State Medical Board of Ohio or Ohio Board of Nursing page read on 2026-09-18 states either that Ohio issues a separate state controlled substance registration for prescribers or that it does not. Ohio''s Board of Pharmacy licenses Terminal Distributors of Dangerous Drugs, which is a different instrument attached to a location rather than to a prescriber, and no page was read that settles the prescriber question. A negative cannot be asserted from silence. NOT SEEDED. OPEN: read ORC ch. 3719 and the Board of Pharmacy''s prescriber guidance.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP OH/MD and OH/APRN renewal_window_days. Neither board publishes the date on which the renewal transaction opens. ORC sec. 4723.24 gives nursing DEADLINES ("An application for renewal of the license is due on the fifteenth day of September of the renewal year"; the licence "lapses on the first day of November of the renewal year") but a deadline and a lapse date are not a window-open date. NOT SEEDED.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP OH/APRN/fingerprint_required and OH/APRN/supervision_required. No Ohio Board of Nursing page read states a fingerprint condition for APRNs. On supervision: ORC 4723.431 requires COLLABORATION via a standard care arrangement and that is what was seeded; nothing read asserts physician SUPERVISION of an Ohio APRN, and the absence of a supervision statement is not a verified "no supervision". NOT SEEDED -- deliberately, because collapsing collaboration into supervision (or writing supervision_required = false from the collaboration rule) would destroy exactly the distinction this asset sells.'),

-- ---- INDIANA --------------------------------------------------------------
(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IN/MD/ce_hours_total and IN/MD/ce_cycle_months. Three Indiana PLA sources were read end to end -- the Physicians Licensing Information page, the Top Ten FAQs for Physician License Renewals, and the Generic MD/DO Active Renewal Form -- and NONE of them states a continuing medical education hour requirement or carries a CME attestation. Indiana is widely understood to impose no general CME mandate on physicians, but WIDELY UNDERSTOOD IS NOT VERIFIED, and unlike Montana no Indiana source publishes the negative in terms. A zero is therefore NOT seeded; Montana''s zero is seeded because the Montana board writes "Montana does not require Physicians to acquire CME", and Indiana''s boards write nothing at all. OPEN: obtain a written statement from the Medical Licensing Board, or read IC 25-22.5-2-7 and 844 IAC 5.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IN/MD/csr_renewal_cycle_months and IN/APRN/csr_renewal_cycle_months. Indiana''s CSR is verified to exist and to be mandatory, and its $60 fee is verified. The PLA page says only that "Each registrant will receive renewal information for their CSR at the same time that he or she receives renewal information for his or her professional license" and that "The Renewal Notice is sent no later than 90 days prior to the expiration" -- which STRONGLY SUGGESTS the CSR runs on the same biennial clock as the underlying licence but does not state a period. A CSR expiry generated from the licence expiry would be an inference, and a wrong CSR date stops a prescriber writing. NOT SEEDED. OPEN: read 856 IAC 2 or obtain the CSR expiry rule. Source: https://www.in.gov/pla/professions/controlled-substance-registration'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IN/APRN/renewal_cycle_months, IN/APRN/renewal_fee_cents, IN/APRN/initial_license_fee_cents and IN/APRN/ce_cycle_months. Indiana PLA''s Nursing Licensing Information page publishes the RN figures -- "Registered Nurse (RN) licenses expire on October 31st of every odd-numbered year", $50 renewal, $50 application -- but says nothing about the expiry date or fee of the APRN / prescriptive authority credential itself, and the two PLA pages that would (.../continuing-education-requirements/ and .../advanced-practice-nurse/) both returned 404 on 2026-09-18. An Indiana APN holds an RN licence, so the RN dates are LIKELY to govern, but carrying a figure from one licence type to another is precisely the inference this standard forbids. NOT SEEDED.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP IN/MD/fingerprint_required, IN/APRN/fingerprint_required, IN/MD/renewal_window_days, IN/APRN/renewal_window_days, IN/APRN/supervision_required. Nothing read on 2026-09-18 addresses fingerprinting for either Indiana profession. On the window: the CSR page gives a 90-day NOTICE period, which is a notice date and not a transaction-open date, and no licence-renewal window was published. On supervision: Indiana''s instrument is a written practice / collaborative agreement, which was seeded; no source asserts supervision, and silence is not a "no". NOT SEEDED.'),

-- ---- WISCONSIN ------------------------------------------------------------
(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'ACCESS GAP WISCONSIN ADMINISTRATIVE CODE. docs.legis.wisconsin.gov refused automated fetch throughout 2026-09-18: chapter Med 13 (physician CE) returned ROBOTS_DISALLOWED twice, once on a robots.txt ConnectTimeout and once on a parse failure, and the 2023 AB 154 / SB 145 bill texts did the same. Wisconsin Admin Code ch. N 8 WAS retrieved, but only because DSPS serves it as a PDF at a different path. CONSEQUENCE: the Wisconsin physician CE total (30 hours) and biennium rest on DSPS web pages and the #570 application information sheet rather than on Med 13 itself, and the opioid hours could not be confirmed as recurring. OPEN: retrieve Med 13 by hand.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP WI/APRN/ce_hours_total. Wis. Admin. Code sec. N 8.05(1) imposes 16 contact hours per biennium IN CLINICAL PHARMACOLOGY OR THERAPEUTICS specifically, including 2 in responsible prescribing of controlled substances. It does NOT state a general continuing education total for the credential, and a topic requirement is not a total. Seeding 16 as ce_hours_total would misrepresent a pharmacology-only duty as the whole CE obligation. NOT SEEDED; the 16 is recorded under ce_topic_pharmacotherapeutics_hours where it belongs. OPEN: establish whether Wisconsin imposes any general APRN CE total, particularly under the new APRN licensure regime.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP WI/MD/initial_license_fee_cents, WI/APRN/initial_license_fee_cents, WI/MD/fingerprint_required, WI/APRN/fingerprint_required, WI/MD/renewal_window_days, WI/APRN/renewal_window_days, WI/MD/csr_required, WI/APRN/csr_required. DSPS''s Renewal Dates and Fees schedule carries RENEWAL fees only; the initial credential fee is in a separate schedule that was not located. Wisconsin''s #570 Medicine and Surgery Application Information sheet gives only an oral examination fee ($266). Nothing read addresses fingerprinting, a renewal-window open date, or a Wisconsin state controlled substance registration for either profession. NOT SEEDED.'),

-- ---- MINNESOTA ------------------------------------------------------------
(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP MN/MD/initial_license_fee_cents and MN/MD/renewal_fee_cents. The Minnesota Board of Medical Practice''s Renew Your License page describes the annual renewal process but prints no amount, and the Board''s fees page at https://mn.gov/boards/medical-practice/licensing/fees/ returned 404 on 2026-09-18. NOT SEEDED. Note this is the ONLY missing piece for MN/MD -- the annual cycle and the three-year 75-hour CME clock are both verified, and they are the two numbers most often conflated for this state.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP MN/APRN/ce_hours_total and MN/APRN/ce_cycle_months. The Minnesota Board of Nursing''s Continuing Education page states "During a typical continuing education participation period (24 months) an RN must participate in 24 contact hours of continuing education" -- but the page addresses RN and LPN renewal and states no APRN figure. A Minnesota APRN holds an RN licence and so is very likely bound by the 24 hours, but carrying a figure from the RN licence to the APRN licence is an inference across license_types and is exactly what this standard forbids. NOT SEEDED. OPEN: read Minn. R. ch. 6310 for the APRN-specific requirement, or obtain a Board statement. Source: https://mn.gov/boards/nursing/licensure/continuing-ed/'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
 'GAP MN/APRN/supervision_required. Minnesota''s verified instrument is a COLLABORATIVE AGREEMENT ending at 2,080 hours, which is seeded as value_json under collaborative_agreement_required. No Minnesota source read asserts physician SUPERVISION of an APRN, and none asserts its absence. A false here would look like a finding; it would be an inference from the presence of a different instrument. NOT SEEDED. This is the distinction the brief calls commercially important and it is preserved deliberately: Minnesota has a collaboration tier, Nebraska has a supervision tier, and the two rows in this seed use different field_keys for that reason.'),

(null, null, null, timestamptz '2026-09-18 00:00:00+00', 'research-agent-group-c', 1, 'unresolved',
